/**
 * SANDBOX-ONLY fixture: a real-scale report for Waterloo, ON (1,883 passes).
 *
 * waterloo.json was generated by scratch/ui-results/fixture.gen.ts from the REAL engine: CelesTrak
 * elements in public/data/catalog.json, SGP4 geometry, the real pass search, for the window
 * 2026-10-27 04:00Z → 2026-11-03 04:00Z, with the imagery leg fed real archive items:
 *   Sentinel-2  S2C_MSIL2A_20261101T161421_R140_T17TNJ_20261102T164803 (cloud 25.5 %)
 *               S2A_MSIL2A_20261027T162651_R040_T17TNJ_20261027T231305 (cloud 38.9 %)
 *               S2B_MSIL2A_20261027T161359_R140_T17TNJ_20261027T200624, S2B_MSIL2A_20261030T162419_R040_T17TNJ_20261030T200303
 *   Landsat     LC09_L2SP_018030_20261031_02_T1 (cloud 11.7 %)
 *   NASA GIBS   VIIRS / MODIS daily true-colour candidates for the daytime in-swath passes
 * Tracks are stripped from the JSON (size) and rebuilt here from the catalog when it is loaded.
 *
 * Never import this from production code.
 */
import { groundTrack, loadCatalog } from '@/engine'
import { gibsWmsUrl, pcCropUrl } from '@/imagery'
import type { Capture, GeoWatcher, Pass, Place, Report } from '@/types'
import raw from './waterloo.json'

type RawCapture = Omit<Capture, 'cropUrl'>
interface RawFixture {
  place: Place
  windowStart: number
  windowEnd: number
  generatedAt: number
  catalogFetchedAt: string
  counts: Report['counts']
  notes: string[]
  geo: GeoWatcher[]
  captures: RawCapture[]
  passes: Omit<Pass, 'track'>[]
}

function inflateCapture(c: RawCapture, place: Place): Capture {
  const at = { lat: place.lat, lon: place.lon }
  if (c.provider === 'gibs') {
    const [layer, date] = c.itemId.split('@')
    return { ...c, cropUrl: (o) => gibsWmsUrl(layer, date, at, o) }
  }
  const coll = c.collection as 'sentinel-2-l2a' | 'landsat-c2-l2'
  return { ...c, cropUrl: (o) => pcCropUrl(coll, c.itemId, at, o) }
}

/** The fixture report. With `withTracks`, ground tracks are rebuilt from the real catalog (~0.2 s). */
export async function waterlooReport({ withTracks = true } = {}): Promise<Report> {
  const f = raw as unknown as RawFixture
  let track = (_p: Omit<Pass, 'track'>): Pass['track'] => []
  if (withTracks) {
    try {
      await loadCatalog()
      track = (p) => groundTrack(p.norad, p.tClosest - 8 * 60_000, p.tClosest + 8 * 60_000, 20)
    } catch {
      /* no catalog: plan views synthesize a straight track */
    }
  }
  return {
    place: f.place,
    windowStart: f.windowStart,
    windowEnd: f.windowEnd,
    generatedAt: f.generatedAt,
    catalogFetchedAt: f.catalogFetchedAt,
    counts: f.counts,
    notes: f.notes,
    geo: f.geo,
    captures: f.captures.map((c) => inflateCapture(c, f.place)),
    passes: f.passes.map((p) => ({ ...p, track: track(p) })),
  }
}

export const WATERLOO: Place = { label: 'Waterloo', sublabel: 'Ontario, Canada', countryCode: 'ca', lat: 43.4723, lon: -80.5449, source: 'demo' }
